"use client";

import { useEffect, useRef } from "react";
import type { Project } from "../content";

type ProjectCardProps = {
  project: Project;
  index: number;
  style?: React.CSSProperties;
  tabIndex?: number;
};

export function ProjectCard({ project, index, style, tabIndex }: ProjectCardProps) {
  const ref = useRef<HTMLAnchorElement>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    if (typeof window === "undefined" || !("IntersectionObserver" in window)) {
      el.classList.add("is-revealed");
      return;
    }
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            el.classList.add("is-revealed");
            observer.disconnect();
          }
        });
      },
      { threshold: 0.15 }
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  return (
    <a
      ref={ref}
      href={project.url || "#"}
      className="group relative block text-left reveal-init border border-line bg-transparent overflow-hidden transition-colors duration-300 hover:border-terracotta/60 focus-ring"
      style={{ transitionDelay: `${index * 80}ms`, ...style }}
      tabIndex={tabIndex}
    >
      {/* Image — wide preview, no scale on hover */}
      <div className="relative aspect-[4/3] overflow-hidden bg-panel">
        <img
          src={project.image}
          alt={`${project.title} — ${project.category}`}
          className="w-full h-full object-cover"
          loading="lazy"
          decoding="async"
        />
      </div>

      {/* Number + title + category */}
      <div className="p-4">
        <span className="font-display text-terracotta text-2xl leading-none">
          {project.number}
        </span>
        <h3 className="font-display text-ink text-lg md:text-xl leading-none mt-1">
          {project.title}
        </h3>
        <p className="text-[10px] tracking-[0.2em] text-muted mt-1 uppercase">
          {project.category}
        </p>
      </div>
    </a>
  );
}